let payload = msg.payload;
if (typeof payload === "string") {
  try { payload = JSON.parse(payload); } catch (e) { return null; }
}
if (typeof payload === "number") {
  payload = { temp1: payload };
}
if (!payload || typeof payload !== "object") {
  node.warn("ThermalTrace bridge: payload must be JSON object");
  return null;
}
msg.headers = {
  "Content-Type": "application/json",
  "X-Ingest-Key": env.get("THERMALTRACE_INGEST_KEY") || "YOUR_DEVICE_KEY"
};
msg.payload = {
  topic: msg.topic || "home/garage/temp",
  message: payload
};
return msg;

let open = msg.payload;
if (typeof open === "string") {
  const s = open.toLowerCase();
  if (s === "open" || s === "on" || s === "true" || s === "1") open = true;
  else if (s === "closed" || s === "off" || s === "false" || s === "0") open = false;
  else try { open = JSON.parse(open); } catch (e) { return null; }
}
if (typeof open === "object" && open != null && "state" in open) {
  open = open.state;
}
if (typeof open !== "boolean") {
  node.warn("Door bridge: expected boolean/open/closed");
  return null;
}
msg.headers = {
  "Content-Type": "application/json",
  "X-Ingest-Key": env.get("THERMALTRACE_INGEST_KEY") || "YOUR_DEVICE_KEY"
};
msg.payload = {
  topic: msg.topic || "home/garage/door",
  message: {
    sensors: [{ key: "garage_door", kind: "door", bool: open }]
  }
};
return msg;
